INSERT INTO "meets" VALUES(1,'AQU-2026-WINTER',1,'Winter Meet','Thoroughbred',2026,'2026-01-01','2026-03-29','2026-01-01..2026-02-15=Thu,Fri,Sat,Sun|2026-02-16..2026-03-29=Fri,Sat,Sun',45,'approved','pattern',NULL,NULL,'NYRA','https://www.nyra.com/aqueduct/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/','NYRA: Thu-Sun through Feb 15, then Fri-Sun.','seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(2,'AQU-2026-SPRING',1,'Spring Meet','Thoroughbred',2026,'2026-04-02','2026-04-26','Thu,Fri,Sat,Sun',15,'approved','pattern',NULL,NULL,'NYRA','https://www.nyra.com/aqueduct/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/',NULL,'seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(3,'AQU-2026-BIGA',1,'Belmont at the Big A Spring/Summer Meet','Thoroughbred',2026,'2026-04-30','2026-06-28','Thu,Fri,Sat,Sun',33,'approved','pattern','2026-05-25','2026-06-04;2026-06-05;2026-06-06;2026-06-07','NYRA','https://www.nyra.com/aqueduct/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/','Run at Aqueduct. The 33 days include the Belmont Stakes Racing Festival at Saratoga (Jun 3-7), which is stored under SAR.','seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(4,'SAR-2026-BSRF',3,'Belmont Stakes Racing Festival','Thoroughbred',2026,'2026-06-03','2026-06-07','Wed,Thu,Fri,Sat,Sun',5,'approved','pattern',NULL,NULL,'NYRA','https://www.nyra.com/saratoga/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/','Belmont Stakes on Sat Jun 6. Third and final year at Saratoga.','seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(5,'SAR-2026-SUMMER',3,'Summer Meet','Thoroughbred',2026,'2026-07-03','2026-09-07','2026-07-03..2026-07-05=Fri,Sat,Sun|2026-07-06..2026-07-28=Thu,Fri,Sat,Sun|2026-07-29..2026-09-01=Wed,Thu,Fri,Sat,Sun|2026-09-02..2026-09-07=Mon,Wed,Thu,Fri,Sat,Sun',46,'approved','pattern',NULL,NULL,'NYRA','https://www.nyra.com/saratoga/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/','Fri-Sun opening weekend; Thu-Sun Jul 9-26; five-day weeks from Jul 29; six-day closing week Sep 2-7.','seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(6,'BEL-2026-FALL',2,'Fall Meet (inaugural meet at the new Belmont Park)','Thoroughbred',2026,'2026-09-18','2026-12-06','Thu,Fri,Sat,Sun',46,'approved','pattern',NULL,NULL,'NYRA','https://www.nyra.com/belmont/news/2026-stakes-schedule-for-belmont-park-fall-meet-out-now/','Weekly pattern is assumed (NYRA''s usual Thu-Sun). 46 days were announced.','seed','2026-10-29 16:04:53');
INSERT INTO "meets" VALUES(7,'BEL-2627-WINTER',2,'Winter Meet 2026-27','Thoroughbred',2026,'2026-12-10','2026-12-31','Thu,Fri,Sat,Sun',11,'approved','pattern',NULL,'2026-12-24','NYRA','https://www.nyra.com/aqueduct/news/nyra-announces-2026-racing-schedule-multi-year-agreement-on-race-dates/','11 race days in Dec 2026; continues into 2027. NYRA''s 2027 calendar (203 days) has not been published yet.','seed','2026-10-29 16:04:53');
